contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address newOwner) public payable {
        require(newOwner != address(0));

        // The test contract is the owner because it deployed C.
        address originalOwner = address(this);

        c.transferOwnership(newOwner); if (__ESBMC_reverted()) return;

        bool finishReverted;
        c.finishDistribution(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            finishReverted = true;
        } else {
            finishReverted = false;
        }

        assert(!finishReverted || newOwner != originalOwner);
    }
}

